                'metadata' => ['developer' => 'Larian Studios', 'publisher' => 'Larian Studios', 'supported_languages' => ['English', 'French', 'German', 'Spanish', 'Polish', 'Russian', 'Simplified Chinese', 'Turkish', 'Portuguese (Brazil)', 'Italian', 'Spanish (Latin America)', 'Traditional Chinese', 'Ukrainian', 'Korean', 'Japanese'], 'supported_operating_systems' => ['Windows', 'macOS']],
