                    'recommended' => ['operating_system' => '64-bit Windows 10', 'processor' => 'Intel Core i7-6700K or AMD Ryzen 7 1800X', 'ram' => '8 GB', 'graphics' => 'NVIDIA GTX 1060 6 GB / GTX 970 or AMD RX 480 8 GB', 'storage' => '80 GB available space', 'additional' => 'Broadband internet connection; listed target is 1080p, 60 FPS, High quality.'],
